 "Cartão excluído": "Card deleted",
 "<div class=\"card\" style=\"margin-bottom:8px\"><div class=\"card-titulo\">💳 Por cartão</div>": "<div class=\"card\" style=\"margin-bottom:8px\"><div class=\"card-titulo\">💳 By card</div>",
